                                    stream: stream,
                                    finalPos: finalPos,
                                    offset: offset,
                                    type: type,
                                    lastParsed: lastParsed,
                                    recordParseCount: recordParseCount,
                                    translationParams: translationParams.WithNoConverter());
                            }
                            case 1:
                            {
                                _EDIDLocation = (stream.Position - offset);
                                return new ParseResult((int)MaterialType_FieldIndex.EDID, type);
                            }
                            default:
                                throw new NotImplementedException();
                        }
                    }
                }
                case RecordTypeInts.PNAM:
                {
                    _ParentLocation = (stream.Position - offset);
                    return (int)MaterialType_FieldIndex.Parent;
                }
                case RecordTypeInts.MNAM:
                {
                    _MNAMLocation = (stream.Position - offset);
                    return (int)MaterialType_FieldIndex.MNAM;
                }
                case RecordTypeInts.CNAM:
                {
