                }
                case RecordTypeInts.FNAM:
                {
                    _FNAMLocation = (stream.Position - offset);
                    return (int)MaterialType_FieldIndex.FNAM;
                }
                case RecordTypeInts.HNAM:
                {
                    _HavokDisplayColorLocation = (stream.Position - offset);
                    return (int)MaterialType_FieldIndex.HavokDisplayColor;
                }
                case RecordTypeInts.ANAM:
                {
                    _ANAMLocation = (stream.Position - offset);
                    return (int)MaterialType_FieldIndex.ANAM;
                }
                case RecordTypeInts.____:
                {
